insert into listings (category_key, title, location, description, image_url, maps_link, whatsapp_number, status, partner_id) values
  ('hotels', 'Park Hyatt Zanzibar', 'Shangani, Stone Town', 'Wake up inside a UNESCO World Heritage Site, where Stone Town''s historic streets meet sweeping Indian Ocean views. Two pools and celebrated dining make this one of Tanzania''s most refined island stays.', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?w=800&q=80', '', '255700000000', 'approved', null),
  ('hotels', 'Emerson Spice Hotel', 'Stone Town, Zanzibar', 'A centuries-old merchant''s house turned romantic hideaway, with 11 individually designed rooms and a legendary rooftop Tea House. Featured among Condé Nast Traveler''s most distinctive stays.', '/images/hotels/emerson-spice.jpeg', '', '255700000000', 'approved', null),
  ('hotels', 'Essque Zalu Zanzibar', 'Nungwi, North Zanzibar', 'Bold and distinctive resort featuring the highest makuti thatched roof on the island, with two restaurants, three bars and a lagoon-style pool just steps from the beach.', 'https://images.unsplash.com/photo-1571003123894-1f0594d2b5d9?w=800&q=80', '', '255700000000', 'approved', null),
  ('hotels', 'The Z Hotel Zanzibar', 'Nungwi Beach, Zanzibar', 'Tanzania''s first designer hotel, featuring furniture by Philippe Starck just steps from Nungwi Beach — rated among the world''s 25 most beautiful beaches.', 'https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?w=800&q=80', '', '255700000000', 'approved', null),
  ('hotels', 'Nungwi Dreams by Mantis', 'Nungwi, North Tip, Zanzibar', 'Beachfront boutique resort on Zanzibar''s highest-rated beach, blending contemporary architecture with Swahili and Arabic design touches.', '/images/hotels/nungwi-dreams.jpeg', '', '255700000000', 'approved', null),
  ('hotels', 'Canary Nungwi Hotel &amp; Spa', 'Nungwi Beach, Zanzibar', 'Beachfront resort with spacious king-size rooms and private balconies, paired with a world-class spa and easy access to Nungwi''s best dive sites.', '/images/hotels/canary-nungwi.jpeg', '', '255700000000', 'approved', null),
  ('hotels', 'Jafferji House', 'Stone Town, Zanzibar', 'An exquisitely restored heritage property tucked into Stone Town''s winding lanes, blending old Zanzibar architecture with elegant modern comfort.', '/images/hotels/jafferji.jpeg', '', '255700000000', 'approved', null),
  ('hotels', 'Sharazād Wonders Boutique', 'Stone Town, Zanzibar', 'Recognised as the most sustainable luxury boutique hotel in East Africa, featured among Condé Nast Traveler''s best hotels for its design and cuisine.', '/images/hotels/sharazad.jpeg', '', '255700000000', 'approved', null),
  ('hotels', 'Zanzibar Serena Hotel', 'Shangani, Stone Town', 'A beautifully restored 19th-century merchant''s house on the Stone Town seafront, combining authentic Swahili architecture with ocean views.', '/images/hotels/zanzibar-serena.jpeg', '', '255700000000', 'approved', null),
  ('hotels', 'Baraza Resort &amp; Spa', 'Bwejuu, South East Zanzibar', 'All-inclusive luxury on Zanzibar''s serene south-east coast, with Arabian-themed architecture, private plunge pools and the award-winning Frangipani Spa.', 'https://images.unsplash.com/photo-1582719508461-905c673771fd?w=800&q=80', '', '255700000000', 'approved', null),
  ('hotels', 'Breezes Beach Club &amp; Spa', 'Bwejuu, East Coast Zanzibar', 'A classic east-coast resort with beachfront bungalows, a PADI dive centre and four restaurants — a well-loved base for divers, snorkellers and families alike.', 'https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?w=800&q=80', '', '255700000000', 'approved', null),
  ('hotels', 'Kilindi Zanzibar', 'Kendwa, North West Zanzibar', 'One of Zanzibar''s most exclusive resorts — just 15 open-plan pavilions with private pools, adults-only and all-inclusive on a pristine north-western beach.', 'https://images.unsplash.com/photo-1540541338287-41700207dee6?w=800&q=80', '', '255700000000', 'approved', null),
  ('beaches', 'Nungwi Beach', 'North Zanzibar', 'Rated among the world''s 25 most beautiful beaches. Faces west for spectacular sunsets. Lively atmosphere with resorts, restaurants, diving schools. The island''s most popular beach destination.', '/images/beaches/nungwi-beach.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-5.7305969999999995,39.291610999999996', '255700000000', 'approved', null),
  ('beaches', 'Kendwa Rocks Beach', 'North West Zanzibar', 'Home to Zanzibar''s most beautiful deep-water beach, where you can swim at any tide without the ocean retreating. Renowned for its powdery soft sands, glamorous sunset views, world-famous full-moon beach parties, and elite beach resort experiences that attract discerning travellers from across the globe.', '/images/beaches/kendwa-rocks-beach.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-5.7522834000000005,39.2881644', '255700000000', 'approved', null),
  ('beaches', 'Paje Beach – Kite Surfing Hub', 'East Coast, Zanzibar', 'A vibrant paradise for active travellers. Famous worldwide for its shallow turquoise lagoons, perfectly consistent trade winds, world-class kite surfing schools, and a lively beachside culture. Whether you are a seasoned rider or a first-time learner, Paje delivers the ultimate east coast adventure.', '/images/beaches/paje-beach-kite-surfing-hub.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.2801542,39.536949799999995', '255700000000', 'approved', null),
  ('beaches', 'Matemwe Beach', 'North East Zanzibar', 'One of the most alluring beaches on Unguja Island – long, peaceful, and fringed by coconut palms. Facing the Mnemba Atoll, it''s a prime spot for snorkelling, sunrise walks, and authentic village life. Tranquil and unspoiled.', '/images/beaches/matemwe-beach.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-5.8204983,39.383505', '255700000000', 'approved', null),
  ('beaches', 'Kizimkazi Beach', 'South Coast, Zanzibar', 'A secluded fishing village on Zanzibar''s south coast, world-famous for wild dolphin sightings. Different from the typical palm-backed lagoon – dramatic coral cliffs and tidal pools make this a unique coastal landscape.', '/images/beaches/kizimkazi-beach.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.4549068,39.4725821', '255700000000', 'approved', null),
  ('beaches', 'Jambiani Beach', 'South East Coast, Zanzibar', 'An authentic fishing village on the south-east coast with a long pristine beach. Famous for seaweed farming – a unique cultural sight. Quieter and more traditional than the north, perfect for those seeking real Zanzibari life.', '/images/beaches/jambiani-beach.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.3208173,39.5485543', '255700000000', 'approved', null),
  ('beaches', 'Fumba Beach', 'South West Zanzibar', 'A secluded peninsula beach on Zanzibar''s south west, accessible via a scenic drive through mangroves. Calm turquoise waters, spectacular dhow sunsets, and significantly fewer crowds than the north. Departure point for Safari Blue excursions.', '/images/beaches/fumba-beach.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=Fumba+Beach+Zanzibar', '255700000000', 'approved', null),
  ('beaches', 'Mangapwani Beach', 'North West Zanzibar', 'A peaceful beach north of Stone Town with historical significance – nearby are the Mangapwani Slave Cave and coral caves used in the 19th century slave trade. Calm waters, soft sand, and a fascinating blend of history and nature.', '/images/beaches/mangapwani-beach.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=Mangapwani+Beach+Zanzibar', '255700000000', 'approved', null),
  ('beaches', 'Bwejuu Beach', 'South East Coast, Zanzibar', 'An unspoiled and remote stretch of beach on Zanzibar''s south east coast. Shallow tidal flats reveal fascinating marine life at low tide. Home to traditional dhow building and the quietest, most authentic east coast experience.', '/images/beaches/bwejuu-beach.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=Bwejuu+Beach+Zanzibar', '255700000000', 'approved', null),
  ('restaurants', 'The Rock Restaurant', 'Michamvi Pingwe, East Zanzibar', 'World-famous culinary destination perched on an iconic ocean rock rising from the turquoise Indian Ocean. At low tide walk across the sand; at high tide, arrive by romantic boat transfer. Experience world-class seafood surrounded by breathtaking 360-degree ocean views as the tide changes around you. Five exclusive sittings daily — reservations essential.', '/images/restaurants/the-rock-restaurant.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.1520657,39.5194093', '255700000000', 'approved', null),
  ('restaurants', 'Emerson Spice Tea House', 'Emerson Spice Hotel, Stone Town', 'Just 25 guests per evening enjoy a seven-course seafood tasting menu under the stars, with sweeping views over Stone Town. Sunset cocktails from 6pm; dinner served at 7pm sharp. Advance reservation required.', '/images/restaurants/emerson-spice-tea-house.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.161221,39.1920628', '255700000000', 'approved', null),
  ('restaurants', 'Emerson Spice Secret Garden', 'Emerson Spice, Stone Town', 'Secluded in a walled garden, this romantic restaurant is a magical haven from Stone Town''s bustle. Live taarab music on Wednesday and Friday evenings. Open for lunch and dinner with a la carte Zanzibari cuisine.', '/images/restaurants/emerson-spice-secret-garden.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.161221,39.1920628', '255700000000', 'approved', null),
  ('restaurants', 'Forodhani Night Market', 'Forodhani Gardens, Stone Town', 'Zanzibar''s most iconic food experience. Every evening at sunset, the waterfront gardens fill with vendors serving Zanzibar pizza, urojo (sour broth soup), fresh seafood grills, sugar cane juice, and Swahili street food at local prices.', '/images/restaurants/forodhani-night-market.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.1603409,39.189002599999995', '255700000000', 'approved', null),
  ('restaurants', '6 Degrees South', 'Shangani Waterfront, Stone Town', 'One of Stone Town''s largest and most vibrant restaurants, named after Zanzibar''s latitude. Features a street terrace and two-storey glass interior with sunset views over Shangani Waterfront. Cosmopolitan menu with Swahili specialties.', '/images/restaurants/6-degrees-south.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.164266,39.1868457', '255700000000', 'approved', null),
  ('restaurants', 'The Silk Route', 'Near Forodhani, Stone Town', 'A long-standing Stone Town favourite near Forodhani Gardens with breezy rooftop seating. Specialties include whole fish from the tandoor, coconut curries, biryanis, and Chinese fusion. Reliable, well-priced, and vegetarian-friendly.', 'https://images.unsplash.com/photo-1519046904884-53103b34b206?w=1000&q=80', 'https://www.google.com/maps/search/?api=1&amp;query=-6.161604,39.188085', '255700000000', 'approved', null),
  ('attractions', 'The Old Fort (Ngome Kongwe)', 'Historical Site – Stone Town', 'Built by Omani Arabs in the early 18th century, this is the oldest surviving structure in Stone Town. Now an arts and cultural centre hosting live performances, the open-air amphitheatre hosts the annual Zanzibar International Film Festival.', '/images/attractions/the-old-fort-ngome-kongwe.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.161438599999999,39.1888708', '255700000000', 'approved', null),
  ('attractions', 'Palace Museum (Beit Al-Sahel)', 'Museum – Stone Town', 'The former royal residence of the Sultans of Zanzibar, Beit Al-Sahel stands proudly on the Stone Town waterfront as one of East Africa''s most important historical monuments. The museum houses an extraordinary collection of Omani royal artefacts including intricately carved royal furniture, ceremonial swords, personal treasures, and historical photographs that chronicle the entire sultanate era. The oceanfront setting, framed by ancient carved wooden doors and whitewashed coral-stone walls, offers a deeply atmospheric window into centuries of Zanzibari royal life and Arab maritime heritage.', '/images/attractions/palace-museum-beit-al-sahel.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.1600521,39.1905176', '255700000000', 'approved', null),
  ('attractions', 'Slave Market &amp; Anglican Cathedral', 'Historical Site – Stone Town', 'One of Africa''s most sobering and important historical sites. The last open slave market in East Africa was abolished in 1873. The Anglican Cathedral built on its site includes a memorial chamber and the original underground slave chambers.', '/images/attractions/slave-market-amp-anglican-cathedral.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.162839600000001,39.192550399999995', '255700000000', 'approved', null),
  ('attractions', 'Jozani-Chwaka Bay National Park', 'National Park – Central Zanzibar', 'Zanzibar''s only national park and a critically important conservation area. The 50km² forest is home to the endangered Zanzibar Red Colobus Monkey – found nowhere else on Earth. Mangrove boardwalks, ancient mahogany trees, and rare birds.', '/images/attractions/jozani-chwaka-bay-national-park.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.241557299999999,39.4139504', '255700000000', 'approved', null),
  ('attractions', 'Forodhani Gardens', 'Cultural Site – Stone Town', 'Also known as Jubilee Gardens, this waterfront park is calm by day and vibrant by night. Historically the ceremonial ground of Zanzibar''s sultans, now the social heart of Stone Town with harbour views, the night food market, and live dhow watching.', '/images/attractions/forodhani-gardens.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.1603409,39.189002599999995', '255700000000', 'approved', null),
  ('attractions', 'Mnemba Atoll Marine Reserve', 'Marine Conservation – North East', 'A private conservation island surrounded by one of the Indian Ocean''s richest coral ecosystems. The atoll is a sanctuary for green turtles, dolphins, whale sharks, and over 400 fish species. World-class diving and snorkelling.', '/images/attractions/mnemba-atoll-marine-reserve.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-5.8204983,39.383505', '255700000000', 'approved', null),
  ('attractions', 'Maruhubi Palace Ruins', 'Historical Ruins – North of Stone Town', 'Hauntingly beautiful and deeply atmospheric, the Maruhubi Palace Ruins stand as a testament to Zanzibar''s opulent sultanate era. Constructed in 1880 by the powerful Sultan Barghash bin Said to house his royal household, the palace once featured grand domed baths, ornate carved stone pillars, elaborate fish ponds fed by fresh springs, and majestic reception chambers. Tragically destroyed by fire in 1899, what remains today — delicate carved columns rising above ancient fish ponds, surrounded by the shade of towering mango and baobab trees — is one of the most romantically evocative archaeological sites on the East African coast.', '/images/attractions/maruhubi-palace-ruins.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=Maruhubi+Palace+Ruins+Zanzibar', '255700000000', 'approved', null),
  ('attractions', 'Kidichi Persian Baths &amp; Spice Farm', 'Cultural Site – Central Zanzibar', 'One of Zanzibar''s most romantic historical treasures, the Kidichi Baths were commissioned in 1850 by Sultan Seyyid Said as an intimate gift for his beloved Persian wife, Binte Irich Mirza. Designed by Persian craftsmen and decorated with remarkably preserved stucco relief carvings depicting geometric and floral patterns, these are the finest and oldest Persian baths surviving in East Africa. The adjacent working spice gardens envelop visitors in an intoxicating sensory journey — warm clove trees, fragrant cinnamon bark, vanilla orchids climbing wooden frames, and cardamom pods glistening in the equatorial light — connecting you directly to the agricultural heritage that made Zanzibar the legendary "Spice Island."', '/images/attractions/kidichi-persian-baths-amp-spice-farm.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=Persian+Baths+Kidichi+Zanzibar', '255700000000', 'approved', null),
  ('attractions', 'Zanzibar Butterfly Centre', 'Nature Centre – Pete Village, Central Zanzibar', 'Tucked within lush tropical forest near Pete village in central Zanzibar, the Butterfly Centre is one of the island''s most enchanting and meaningful experiences. This award-winning community conservation project invites visitors to walk through large screened enclosures where hundreds of indigenous free-flying butterflies — including rare swallowtails, vivid citrus yellows, and iridescent blue species — dance among flowering plants native to the archipelago. Managed and run by local Zanzibari families, the centre provides sustainable livelihoods while educating visitors on butterfly ecology, indigenous plant species, and the vital role of forest conservation in protecting Zanzibar''s unique biodiversity.', '/images/attractions/zanzibar-butterfly-centre.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=Zanzibar+Butterfly+Centre', '255700000000', 'approved', null),
  ('heritage', 'Stone Town', 'UNESCO World Heritage Site – Stone Town', 'A UNESCO World Heritage Site and the historic heart of Zanzibar City. Wander narrow winding alleys lined with coral-stone buildings, ornately carved wooden doors, and centuries of Swahili, Arab, Persian, Indian and European architectural influence.', '/images/heritage/stone-town.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=Stone+Town+Zanzibar', '255700000000', 'approved', null),
  ('heritage', 'Old Fort (Ngome Kongwe)', 'Historical Site – Stone Town', 'Built by Omani Arabs in the early 18th century, this is the oldest surviving structure in Stone Town. Now an arts and cultural centre hosting live performances and the annual Zanzibar International Film Festival.', '/images/heritage/old-fort-ngome-kongwe.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.161438599999999,39.1888708', '255700000000', 'approved', null),
  ('heritage', 'House of Wonders (Beit al-Ajaib)', 'Historic Palace – Stone Town', 'Once the tallest building in East Africa and the first in the region with electric lighting and an elevator. Built in 1883 as a ceremonial palace for Sultan Barghash, it remains an iconic landmark of the Stone Town waterfront.', '/images/heritage/house-of-wonders-beit-al-ajaib.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=House+of+Wonders+Zanzibar', '255700000000', 'approved', null),
  ('heritage', 'Palace Museum (Beit Al-Sahel)', 'Museum – Stone Town', 'The former royal residence of the Sultans of Zanzibar, standing on the Stone Town waterfront as one of East Africa''s most important historical monuments, with royal furniture, ceremonial swords and historical photographs.', '/images/heritage/palace-museum-beit-al-sahel.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.1600521,39.1905176', '255700000000', 'approved', null),
  ('heritage', 'Maruhubi Palace Ruins', 'Historical Ruins – North of Stone Town', 'Constructed in 1880 by Sultan Barghash bin Said to house his royal household, this hauntingly beautiful site once featured grand domed baths and ornate carved pillars. Carved columns now rise above ancient fish ponds shaded by baobab trees.', '/images/heritage/maruhubi-palace-ruins.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=Maruhubi+Palace+Ruins+Zanzibar', '255700000000', 'approved', null),
  ('heritage', 'Hamamni Persian Baths', 'Historic Bathhouse – Stone Town', 'Built in the 1880s by Sultan Barghash, Hamamni ("place of the baths") was Zanzibar''s first public Persian-style bathhouse. Its domed chambers, steam rooms and original plumbing offer a glimpse into 19th-century Stone Town daily life.', '/images/heritage/hamamni-persian-baths.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=Hamamni+Persian+Baths+Zanzibar', '255700000000', 'approved', null),
  ('experiences', 'The Rock Restaurant', 'Michamvi, East Zanzibar', 'World-famous culinary destination perched on an iconic ocean rock. Experience world-class seafood surrounded by 360-degree Indian Ocean views as the tide changes. Arrive by boat at high tide for a truly cinematic entrance.', '/images/experiences/the-rock-restaurant.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.1520657,39.5194093', '255700000000', 'approved', null),
  ('experiences', 'Paje Beach – Kite Surfing Hub', 'Paje, East Coast Zanzibar', 'A vibrant paradise for active travelers. Famous worldwide for its shallow turquoise lagoons, steady trade winds, world-class kite surfing schools, and lively beachside culture. The east coast''s ultimate adventure destination.', '/images/experiences/paje-beach-kite-surfing-hub.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.2801542,39.536949799999995', '255700000000', 'approved', null),
  ('experiences', 'Nakupenda Sandbank Tour', 'Nakupenda Island, Zanzibar', 'A breathtaking full-day excursion to a pristine, disappearing white sandbank. Enjoy sunbathing, premium snorkelling among vibrant coral reefs, and a lavish beachside live-cooked seafood buffet with the Indian Ocean as your dining room.', '/images/experiences/nakupenda-sandbank-tour.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=Nakupenda+Beach+Zanzibar', '255700000000', 'approved', null),
  ('experiences', 'Kendwa Rocks Beach', 'Kendwa, North West Zanzibar', 'Home to Zanzibar''s most beautiful deep-water beach, where you can swim at any tide. Renowned for its powdery soft sands, glamorous sunset views, and elite beach resort experiences that make every moment unforgettable.', '/images/experiences/kendwa-rocks-beach.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-5.7522834000000005,39.2881644', '255700000000', 'approved', null),
  ('caves', 'Kuza Cave', 'South Coast, Zanzibar', 'A breathtaking natural freshwater cave pool hidden beneath the coral landscape of the south coast. Crystal-clear waters cascade into an underground chamber adorned with ancient stalactites — a surreal swimming experience cherished by locals and travellers alike. Revered as a sacred site by the local community, Kuza Cave offers a rare blend of natural wonder and cultural spirituality.', '/images/caves/kuza-cave.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.3034491,39.533964999999995', '255700000000', 'approved', null),
  ('caves', 'Maalum Cave', 'Southeast Zanzibar', 'Meaning "known" in Swahili, Maalum Cave is famous among those in the know — a stunning natural rock pool nestled within a coral cave, where you can swim in serene turquoise waters surrounded by towering limestone walls. Sunlight pierces through the cave opening at midday, casting a magical glow across the water. A true hidden gem of Zanzibar''s southeast coast.', '/images/caves/maalum-cave.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.277524199999999,39.5308595', '255700000000', 'approved', null),
  ('caves', 'Mangapwani Coral Cave', 'North of Stone Town', 'A hauntingly beautiful cave carved into Zanzibar''s ancient coral rock, bearing silent witness to one of history''s darkest chapters. Once used as a holding chamber for enslaved people after the official abolition of slavery, this cave carries immense historical weight. Today it stands as a site of solemn remembrance and extraordinary natural architecture — its cathedral-like coral chambers echoing with both beauty and memory.', '/images/caves/mangapwani-coral-cave.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.00175,39.1912222', '255700000000', 'approved', null),
  ('caves', 'Kiwengwa Caves', 'Kiwengwa, East Coast', 'Stretching along Zanzibar''s scenic east coast, the Kiwengwa Caves are a dramatic series of coral rock formations sculpted by centuries of ocean erosion. Wander through arched tunnels, narrow passages, and open chambers where light filters dramatically through coral ceilings. Combine a cave visit with the pristine white sands of Kiwengwa Beach for a perfect half-day adventure off the beaten path.', '/images/caves/kiwengwa-caves.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-5.998107699999999,39.3594794', '255700000000', 'approved', null),
  ('nature', 'Mangrove Forests', 'Menai Bay &amp; Coastal Inlets', 'Zanzibar''s mangrove forests are among the most ecologically rich ecosystems in the Indian Ocean region, sheltering juvenile fish, crabs, kingfishers, and migratory birds within a labyrinth of tangled roots and tidal channels. Glide silently by kayak or traditional dugout canoe through Menai Bay''s winding waterways at sunrise — a meditation in green, gold, and still water. These vital forests also protect Zanzibar''s coastline from erosion, making them guardians of the island itself.', '/images/nature/mangrove-forests.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.292431499999999,39.4278062', '255700000000', 'approved', null),
  ('nature', 'Red Colobus Monkey Experience', 'Jozani Forest, Central Zanzibar', 'The Kirk''s Red Colobus — Zanzibar''s most iconic and beloved wild resident — exists nowhere else on Earth. Found only in the ancient groves of Jozani Chwaka Bay National Park, these stunning rust-and-black primates swing through the forest canopy with effortless grace, often descending close to visitors with remarkable calm. Walking quietly along forest trails among resident troops is one of Zanzibar''s most profoundly moving wildlife encounters. Guided walks are available daily, and your visit supports vital conservation efforts protecting this endangered endemic species.', '/images/nature/red-colobus-monkey-experience.jpeg', 'https://www.google.com/maps/search/?api=1&amp;query=-6.241557299999999,39.4139504', '255700000000', 'approved', null);